// File: scripts/docs-agent-gitattributes.test.mjs
// Lock: the line `docs-agent/** text eol=lf` in the repository's REAL
// .gitattributes must stay. The docs-agent freshness gate
// (scripts/verify-agent-docs-fresh.mjs) compares generated bytes raw against
// HEAD; without the LF pin a Windows checkout with core.autocrlf=true writes
// CRLF under docs-agent/ and the gate goes falsely red on an otherwise fresh
// tree. CI runs on Linux where that fault class cannot occur, so deleting
// the line would silently re-introduce the false red on Windows -- measured:
// with the line removed, the whole vitest suite, the -Strict validator and
// local-ci were all green. This test is the protection against that.
//
// The check asks GIT ITSELF about the real repository (git check-attr), the
// same pattern Get-GitDeclaredLineEnding in
// scripts/omp/validate-component-versions.helpers.ps1 uses for the embedded
// SQL file, and it is FAIL-CLOSED the same way: git not answering (non-zero
// exit, empty output, an attribute git reports as unspecified) is a FAILURE,
// never a pass. The fixture tests in verify-agent-docs-fresh.test.mjs write
// their OWN .gitattributes into scratch repos; nothing else reads the real
// one.
//
// This test is reachable from `npm test` (vitest) so CI's `npm test` step
// enforces it on every PR without a separate PowerShell harness;
// validate-component-versions.ps1 -Strict and scripts/local-ci.ps1 only run
// on Windows developer machines, which no PR gate executes. `git check-attr`
// behaves identically on Linux, so the test is meaningful in CI even though
// the fault class only bites on Windows checkouts.
import assert from 'node:assert/strict';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { test } from 'vitest';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const REMEDY =
  'Restore the line "docs-agent/** text eol=lf" in the repository .gitattributes. ' +
  'Without it a Windows checkout writes CRLF under docs-agent/ and the freshness gate ' +
  '(scripts/verify-agent-docs-fresh.mjs, local-ci step 4, agent-docs.yml) goes falsely ' +
  'red on an otherwise fresh tree.';

function git(args) {
  return spawnSync('git', ['-c', 'core.quotepath=off', ...args], { cwd: repoRoot, encoding: 'utf8' });
}

test('the real .gitattributes pins LF for every tracked docs-agent file (git check-attr)', () => {
  // Enumerate REAL tracked files rather than hardcoding a name a future
  // regeneration could delete.
  const ls = git(['ls-files', '-z', '--', 'docs-agent']);
  assert.equal(ls.status, 0, `git ls-files failed (exit ${ls.status}): ${ls.stderr}\n${REMEDY}`);
  const tracked = ls.stdout.split('\0').filter(Boolean);
  assert.ok(tracked.length > 0, `git tracks no files under docs-agent/\n${REMEDY}`);

  // One check-attr call for every tracked file, NUL-separated triplets
  // (path\0attribute\0value) so paths with spaces cannot corrupt the parse.
  const attr = git(['check-attr', '-z', 'text', 'eol', '--', ...tracked]);
  // Fail-closed: git not answering is a failure, never a pass.
  assert.equal(attr.status, 0, `git check-attr failed (exit ${attr.status}): ${attr.stderr}\n${REMEDY}`);
  assert.ok(attr.stdout.length > 0, `git check-attr printed nothing\n${REMEDY}`);
  const fields = attr.stdout.split('\0').filter(Boolean);
  assert.equal(fields.length % 3, 0, `unexpected check-attr output shape\n${REMEDY}`);
  const declared = new Map();
  for (let i = 0; i + 2 < fields.length; i += 3) {
    const [file, attribute, value] = [fields[i], fields[i + 1], fields[i + 2]];
    if (!declared.has(file)) declared.set(file, {});
    declared.get(file)[attribute] = value;
  }
  for (const file of tracked) {
    const attributes = declared.get(file) || {};
    assert.equal(
      attributes.text,
      'set',
      `${file}: .gitattributes must set the text attribute for docs-agent/** (got "${attributes.text}")\n${REMEDY}`,
    );
    assert.equal(
      attributes.eol,
      'lf',
      `${file}: .gitattributes must declare eol=lf for docs-agent/** (got "${attributes.eol}")\n${REMEDY}`,
    );
  }
});
